    TEST_ASSERT_EQUAL_STRING("rgb(175, 179, 233)", ip("hsl(235, 56.6565%, 79.8485%)", "hsl(235, 56.6565%, 79.8485%)", 5000, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(16, 4, 11)", ip("hsl(322, 61.2956%, 3.7685%)", "hsl(322, 61.2956%, 3.7685%)", 5000, 2));
